UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The course prepares students to work in a diverse range of fields including health and mental health, child and family welfare, cross-cultural work and work with Aboriginal and Torres Strait Islander peoples, youth work, homelessness, domestic and family violence, disability, drug and alcohol, community development, and advocacy. Underpinned by core principles of social justice and human rights, the course engages students in contemporary anti-oppressive, decolonised and trauma-informed approaches to social work practice. This high job growth area offers a variety of careers in client service roles, service management, research, strategy and policy development. Core units within the course cover essential theories, methods and skills for social work practice with individuals, families, groups and communities. These are complemented by foundational studies in Indigenous world views, sociology, politics, human development and social research. The Bachelor of Social Work (Honours) is designed for social work students who are interested in designing their own research project or pursuing further studies at a postgraduate level.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 104000,
    onshore_tuition_fee = NULL,
    enrolment_fee = 8000,
    materials_fee = NULL,
    entry_requirements = '',
