WHERE cricos_course_code = '102204F';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Bachelor of Midwifery prepares you for entry to professional midwifery practice. You will develop the skills and knowledge necessary to provide quality, woman-centred care through safe and effective midwifery practice in accordance with the Australian Nursing and Midwifery Accreditation Council standards for practice. Study areas include anatomy and physiology, midwifery theory and practice, primary healthcare, perinatal mental health, care during preconception, pregnancy, labour and birth, and early parenting. Graduates will be equipped to work in multi-disciplinary teams and in partnership with women to contribute to healthier outcomes for mother and baby. Graduates of this degree will be eligible for registration with the Australian Health Practitioner Regulation Agency (AHPRA) and practice as a Registered Midwife across a range of settings. Key information to be aware of prior to enrolling: Admission requirements including English language proficiency Requirements for placement in health practice settings Inherent requirements: the abilities required to complete the degree Registration with the NMBA This course has travel expectations — please read information below about placements carefully.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 78000,
