    updated_at = NOW()
WHERE cricos_course_code = '112800C';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Speech pathologists assess and treat adults and children exhibiting acquired or congenital disorders of speech, fluency, voice, language, swallowing and multimodal communication. The Bachelor of Speech Pathology prepares you for entry into professional speech pathology practice. Topics covered include phonetics and linguistics, audiology and neurology, working alongside and interacting with students from other health disciplines. As well as taking advantage of our state-of-the-art facilities, you will receive hands on experience via clinical placements that total 910 hours in schools, hospitals, nursing homes and the Southern Cross University Health Clinics at our Gold Coast, Lismore and Coffs Harbour campuses. Career opportunities for speech pathologists continue to grow nationally and internationally, often working with various specialists in diverse settings such as private practice, not for profit organisations as well as government health and education services. Please note: This course has travel expectations — please read the information below on placements carefully.</p>',
